sql.if:
WITH filtered_dur AS (SELECT /*+ MATERIALIZE */ ingr_a_name, ingr_b_name, taboo_type FROM medication_interactions d WHERE 1=1 ),
dur_keys AS (
  SELECT LOWER(REGEXP_REPLACE(ingr_a_name, '[[:space:]]', '')) ingredient FROM filtered_dur
  UNION SELECT LOWER(REGEXP_REPLACE(ingr_b_name, '[[:space:]]', '')) FROM filtered_dur WHERE taboo_type=4 AND ingr_b_name IS NOT NULL
), med_ingredients AS (
  SELECT /*+ MATERIALIZE */ m.medication_id, LOWER(REGEXP_REPLACE(part.ingredient, '[[:space:]]', '')) ingredient
  FROM medications m CROSS APPLY (
     SELECT REGEXP_SUBSTR(m.material_name, '[^/]+', 1, LEVEL) ingredient FROM dual
     CONNECT BY LEVEL <= REGEXP_COUNT(m.material_name, '/') + 1
  ) part WHERE m.material_name IS NOT NULL
), dur_matches AS (
  SELECT DISTINCT mi.medication_id FROM med_ingredients mi JOIN dur_keys dk ON dk.ingredient=mi.ingredient
)
